<template>
  <main class="kvm-page managed-clusters-page">
    <header class="page-head"><div><span class="eyebrow">{{ t('eyebrow') }}</span><h1>{{ t('title') }}</h1><p>{{ t('subtitle') }}</p></div><button class="btn role-secondary" @click="goBack">{{ t('back') }}</button></header>
    <div class="notice"><strong>{{ t('scopeTitle') }}</strong><p>{{ t('scopeHelp') }}</p></div>
    <div v-if="error" class="banner error" role="alert">{{ error }}</div>
    <section v-if="canManage" class="group-form">
      <h2>{{ t('createTitle') }}</h2><p>{{ t('createHelp') }}</p>
      <form @submit.prevent="createGroup"><label>{{ t('name') }}<input v-model.trim="name" maxlength="80" required></label><p v-if="availableHosts.length < 2" class="host-availability" role="status">{{ t('notEnoughFreeHosts') }}</p><div v-else class="host-grid"><label v-for="host in availableHosts" :key="host.id" class="host-option"><input v-model="selectedHostIds" type="checkbox" :value="host.id"><span><strong>{{ host.hostname || host.name }}</strong><small>{{ host.address }} · {{ t('ready') }}</small></span></label></div><div class="actions"><button class="btn role-primary" :disabled="saving || selectedHostIds.length < 2">{{ saving ? t('creating') : t('create') }}</button></div></form>
    </section>
    <section v-else class="notice"><strong>{{ t('readOnly') }}</strong><p>{{ t('readOnlyHelp') }}</p></section>
    <section class="group-list"><div class="section-head"><h2>{{ t('groupsTitle') }}</h2><button class="btn role-secondary btn-sm" :disabled="loading" @click="load">{{ t('refresh') }}</button></div><p v-if="!groups.length" class="empty">{{ t('empty') }}</p><article v-for="group in groups" :key="group.id" class="group-row"><div><strong>{{ group.name }}</strong><small>{{ memberNames(group) }}</small><span class="state warning-state"><i></i>{{ t('setupState') }}</span></div><div class="actions"><button class="btn role-secondary btn-sm" @click="openGroup(group)">{{ t('open') }}</button><button v-if="canManage" class="btn role-link btn-sm danger-text" @click="removeGroup(group)">{{ t('removeGroup') }}</button></div></article></section>
    <section v-if="selectedGroup" class="inventory"><div class="section-head"><div><h2>{{ selectedGroup.name }}</h2><small>{{ inventory?.checked_at ? `${t('checked')}: ${dateLabel(inventory.checked_at)}` : '' }}</small></div><button class="btn role-secondary btn-sm" :disabled="inventoryLoading" @click="loadInventory">{{ inventoryLoading ? t('loading') : t('refresh') }}</button></div>
      <div class="notice compact"><strong>{{ t('capabilityTitle') }}</strong><p>{{ t('capabilityHelp') }}</p></div>
      <div v-if="inventoryError" class="banner error" role="alert">{{ inventoryError }}</div>
      <section v-if="inventory" class="group-assessment" aria-labelledby="group-assessment-title">
        <div class="assessment-heading"><div><span class="eyebrow">{{ t('assessmentEyebrow') }}</span><h3 id="group-assessment-title">{{ t('assessmentTitle') }}</h3></div><span class="state" :class="groupAssessment.readyForComparison ? 'ready' : 'warning-state'"><i></i>{{ t(groupAssessment.readyForComparison ? 'assessmentHostsReady' : 'assessmentHostsIncomplete', { ready: groupAssessment.readyHostCount, total: groupAssessment.hostCount }) }}</span></div>
        <div class="assessment-grid">
          <article><small>{{ t('architecture') }}</small><strong>{{ groupAssessment.architecture || t(groupAssessment.architectureMismatch ? 'architectureMismatch' : 'architectureUnknown') }}</strong></article>
          <article><small>{{ t('aggregateVcpu') }}</small><strong>{{ groupAssessment.totalVcpus }}</strong></article>
          <article><small>{{ t('aggregateMemory') }}</small><strong>{{ formatMemory(groupAssessment.totalMemoryKib) }}</strong><span>{{ t('aggregateAvailableMemory', { value: formatMemory(groupAssessment.availableMemoryKib) }) }}</span></article>
          <article><small>{{ t('virtualMachineCount') }}</small><strong>{{ groupAssessment.virtualMachineCount }}</strong><span>{{ t('runningVirtualMachineCount', { count: groupAssessment.runningVirtualMachineCount }) }}</span></article>
        </div>
        <div class="assessment-shared-grid">
          <article><strong>{{ t('commonStorageNames') }}</strong><p v-if="!groupAssessment.commonStoragePoolDetails.length">{{ t('noCommonStorageNames') }}</p><p v-if="groupAssessment.inactiveStoragePoolCount" class="resource-warning" role="note">{{ t('inactiveStoragePools', { count: groupAssessment.inactiveStoragePoolCount }) }}</p><p v-if="groupAssessment.unknownStoragePoolStateCount" class="resource-warning" role="note">{{ t('unknownStoragePoolStates', { count: groupAssessment.unknownStoragePoolStateCount }) }}</p><div v-for="pool in groupAssessment.commonStoragePoolDetails" :key="pool.name" class="resource-comparison"><p><strong>{{ pool.name }}</strong> · {{ t(pool.configurationMatches ? 'matchingPoolDefinition' : 'differentPoolDefinition') }}</p><small v-for="entry in pool.entries" :key="entry.hostName">{{ entry.hostName }}: {{ entry.type || '—' }} · {{ entry.target || '—' }} · {{ t(`libvirtState.${entry.state}`) }}</small><small v-for="entry in pool.mountEntries" :key="`${entry.hostName}-mount`">{{ entry.hostName }} {{ t('poolBackingFilesystem') }}: {{ entry.source || '—' }} · {{ entry.type || '—' }} · {{ entry.mountpoint || '—' }}</small><small v-if="pool.sharedNfsCandidate" class="resource-note">{{ t('sharedNfsCandidateReview') }}</small><small v-else>{{ t(pool.filesystemIdentityMatches === true ? 'matchingFilesystemIdentity' : pool.filesystemIdentityMatches === false ? 'differentFilesystemIdentity' : 'unknownFilesystemIdentity') }}</small></div><small>{{ t('storageNamesAreNotProof') }}</small></article>
          <article><strong>{{ t('commonNetworkNames') }}</strong><p v-if="!groupAssessment.commonNetworkDetails.length">{{ t('noCommonNetworkNames') }}</p><p v-if="groupAssessment.inactiveLibvirtNetworkCount" class="resource-warning" role="note">{{ t('inactiveLibvirtNetworks', { count: groupAssessment.inactiveLibvirtNetworkCount }) }}</p><p v-if="groupAssessment.unknownLibvirtNetworkStateCount" class="resource-warning" role="note">{{ t('unknownLibvirtNetworkStates', { count: groupAssessment.unknownLibvirtNetworkStateCount }) }}</p><div v-for="network in groupAssessment.commonNetworkDetails" :key="network.name" class="resource-comparison"><p><strong>{{ network.name }}</strong> · {{ t(network.configurationMatches ? 'matchingNetworkDefinition' : 'differentNetworkDefinition') }}</p><small v-for="entry in network.entries" :key="entry.hostName">{{ entry.hostName }}: {{ entry.mode || '—' }} · {{ entry.bridge || '—' }} · {{ t(`libvirtState.${entry.state}`) }}</small><small v-for="entry in network.bridgeEntries" :key="`${entry.hostName}-bridge`">{{ entry.hostName }}: {{ entry.bridge || '—' }} · {{ t(entry.present === true ? 'bridgeInterfacePresent' : entry.present === false ? 'bridgeInterfaceMissing' : 'bridgeInterfaceUnknown') }} · {{ entry.operstate || '—' }} · MTU {{ entry.mtu ?? '—' }}</small><small>{{ t(network.bridgePresentOnAll === true ? 'bridgePresentOnAllHosts' : network.bridgePresentOnAll === false ? 'bridgeMissingOnHosts' : 'bridgePresenceUnknown') }}</small></div><small>{{ t('networkNamesAreNotProof') }}</small></article>
        </div>
        <p class="assessment-caveat" role="note">{{ t('assessmentCaveat') }}</p>
      </section>
      <div v-if="inventory" class="table-wrap"><table class="table"><thead><tr><th>{{ t('host') }}</th><th>{{ t('hostState') }}</th><th>{{ t('vms') }}</th><th>{{ t('storage') }}</th><th>{{ t('networks') }}</th></tr></thead><tbody><tr v-for="host in inventory.hosts" :key="host.host_id"><td><strong>{{ host.host_name }}</strong></td><td>{{ host.status }}<small v-if="host.status === 'error'" class="inventory-error">{{ t(`inventoryError.${host.error_code || 'inventory_failed'}`) }}</small></td><td>{{ host.vms?.length || 0 }}<small v-for="vm in host.vms" :key="vm.name">{{ vm.name }} · {{ vm.state || vm.status }}</small></td><td><small v-for="pool in host.storage_pools || []" :key="pool.name">{{ pool.name }}</small><span v-if="!host.storage_pools?.length">—</span></td><td><small v-for="network in host.libvirt_networks || []" :key="network.name">{{ network.name }}</small><span v-if="!host.libvirt_networks?.length">—</span></td></tr></tbody></table></div>
      <h3>{{ t('crossHostVms') }}</h3><div v-if="inventory?.vms?.length" class="vm-cards"><article v-for="vm in inventory.vms" :key="`${vm.host_id}-${vm.name}`"><strong>{{ vm.name }}</strong><small>{{ vm.host_name }}</small><span>{{ vm.state || vm.status }}</span></article></div><p v-else class="empty">{{ t('noVms') }}</p>
    </section>
  </main>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { assessKvmGroupInventory, availableKvmGroupHosts } from '../utils/kvm-group-readiness';
const apiBase = (process.env.VUE_APP_KVM_API || '/kvm-api').replace(/\/$/, '');
export default defineComponent({
  name: 'ManagedKvmClusters',
  data() { return { name: '', hosts: [] as any[], groups: [] as any[], selectedHostIds: [] as string[], selectedGroup: null as any, inventory: null as any, loading: false, saving: false, inventoryLoading: false, error: '', inventoryError: '', canManage: false }; },
  computed: {
    availableHosts(): any[] { return availableKvmGroupHosts(this.hosts, this.groups); },
    groupAssessment() { return assessKvmGroupInventory(this.inventory); },
  },
  mounted() { this.load(); },
  methods: {
    t(key: string) { const translate = (this as any).$store?.getters?.['i18n/t']; return translate ? translate(`kvmManager.managedClusters.${key}`) : key; },
    async request(path: string, options: RequestInit = {}) { const response = await fetch(`${apiBase}${path}`, { credentials: 'include', cache: 'no-store', ...options, headers: { ...(options.body ? { 'Content-Type': 'application/json' } : {}), ...(options.headers || {}) } }); const body = response.status === 204 ? null : await response.json().catch(() => ({})); if (!response.ok) throw new Error(body?.detail || `Request failed (${response.status})`); return body; },
    async load() { this.loading = true; this.error = ''; try { [this.groups, this.hosts] = await Promise.all([this.request('/managed-clusters'), this.request('/hosts')]); const permissions = await this.request('/permissions'); this.canManage = Boolean(permissions?.canManageClusters); } catch (error) { this.error = (error as Error).message; } finally { this.loading = false; } },
    async createGroup() { if (this.selectedHostIds.length < 2) return; this.saving = true; this.error = ''; try { const created = await this.request('/managed-clusters', { method: 'POST', body: JSON.stringify({ name: this.name, host_ids: this.selectedHostIds }) }); this.name = ''; this.selectedHostIds = []; await this.load(); this.openGroup(created); } catch (error) { this.error = (error as Error).message; } finally { this.saving = false; } },
    async openGroup(group: any) { this.selectedGroup = group; await this.loadInventory(); },
    async loadInventory() { if (!this.selectedGroup) return; this.inventoryLoading = true; this.inventoryError = ''; try { this.inventory = await this.request(`/managed-clusters/${this.selectedGroup.id}/inventory`); } catch (error) { this.inventoryError = (error as Error).message; } finally { this.inventoryLoading = false; } },
    async removeGroup(group: any) { try { await this.request(`/managed-clusters/${group.id}`, { method: 'DELETE' }); if (this.selectedGroup?.id === group.id) { this.selectedGroup = null; this.inventory = null; } await this.load(); } catch (error) { this.error = (error as Error).message; } },
    memberNames(group: any) { return (group.members || []).map((host: any) => host.hostname || host.name).join(', '); },
    dateLabel(value: string) { const date = new Date(value); if (Number.isNaN(date.getTime())) return value; const locale = (this as any).$store?.state?.i18n?.selected; return date.toLocaleString(locale || undefined); },
    formatMemory(value: number) { return `${(Math.max(0, value) / 1048576).toLocaleString(undefined, { maximumFractionDigits: 1 })} GiB`; },
    goBack() { (this as any).$router?.push({ name: 'kvm-c-clusters', params: { cluster: '_' } }); },
  },
});
</script>

<style scoped>
.managed-clusters-page{max-width:1160px;margin:0 auto;padding:24px;box-sizing:border-box}.page-head,.section-head,.group-row{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.page-head{margin-bottom:18px}.page-head h1{margin:4px 0;font-weight:500}.page-head p,.group-form>p,.section-head small{color:var(--muted,#929baa)}.eyebrow{font-size:10px;letter-spacing:.08em;color:var(--muted,#929baa)}.notice{margin:14px 0;padding:13px 15px;border-left:3px solid var(--primary,#4b91e2);background:color-mix(in srgb,var(--primary,#4b91e2) 9%,var(--body-bg,#252b33));border-radius:4px}.notice p{margin:4px 0 0;color:var(--muted,#a4adba);font-size:13px;line-height:1.45}.compact{margin:10px 0}.group-form,.group-list,.inventory{margin:18px 0;padding:18px;border:1px solid var(--border,#394452);border-radius:7px;background:var(--body-bg,#252b33)}.group-form h2,.group-list h2,.inventory h2{margin:0;font-size:18px}.group-form form>label{display:grid;gap:6px;max-width:480px;font-size:13px;font-weight:600}.group-form input:not([type=checkbox]){height:38px;padding:8px;border:1px solid var(--border,#4b5563);border-radius:4px;background:var(--kvm-control-bg,var(--body-bg,#252b33));color:var(--kvm-control-text,var(--body-text,#e5e7eb))}.host-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:8px;margin:16px 0}.host-option{display:flex;align-items:center;gap:10px;padding:11px;border:1px solid var(--border,#394452);border-radius:5px;cursor:pointer}.host-option span,.group-row small,.vm-cards small{display:block}.host-option small,.group-row small{margin-top:4px;color:var(--muted,#929baa);font-size:12px}.host-availability{margin:12px 0;padding:10px 12px;border:1px dashed var(--border,#394452);border-radius:5px;color:var(--muted,#929baa);font-size:12px;line-height:1.45}.actions{display:flex;gap:8px;align-items:center}.group-row{align-items:center;padding:13px 0;border-top:1px solid var(--border,#394452)}.group-row>div:first-child{display:grid;gap:4px}.state{display:inline-flex;align-items:center;gap:5px;color:var(--kvm-warning,#8b5a00);font-size:12px}.state i{width:7px;height:7px;border-radius:50%;background:currentColor}.empty{padding:16px;text-align:center;color:var(--muted,#929baa)}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:10px;text-align:left;border-bottom:1px solid var(--border,#394452);vertical-align:top}.table td small{display:block;margin-top:4px;color:var(--muted,#929baa)}.table td small.inventory-error{color:var(--kvm-danger,#b42318)}.inventory h3{margin:22px 0 10px;font-size:16px}.vm-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.vm-cards article{display:grid;gap:5px;padding:12px;border:1px solid var(--border,#394452);border-radius:5px}.vm-cards small{color:var(--muted,#929baa)}.danger-text{color:var(--kvm-danger,#b42318)}.group-assessment{margin:16px 0;padding:14px;border:1px solid var(--border,#394452);border-radius:6px;background:color-mix(in srgb,var(--body-text,#eee) 2%,var(--body-bg,#252b33))}.assessment-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.assessment-heading h3{margin:4px 0 0;font-size:16px}.assessment-grid,.assessment-shared-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px;margin-top:12px}.assessment-grid article,.assessment-shared-grid article{display:grid;align-content:start;gap:4px;min-width:0;padding:10px;border:1px solid var(--border,#394452);border-radius:5px}.assessment-grid small,.assessment-shared-grid small,.assessment-grid article>span{color:var(--muted,#929baa);font-size:11px;line-height:1.4}.assessment-grid strong{font-size:14px;overflow-wrap:anywhere}.assessment-shared-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.assessment-shared-grid p{margin:2px 0;overflow-wrap:anywhere;font-size:13px}.assessment-shared-grid p.resource-warning{color:var(--kvm-warning,#b58a22)}.assessment-caveat{margin:11px 0 0;padding:9px 10px;border-left:3px solid var(--kvm-warning,#b58a22);background:color-mix(in srgb,var(--kvm-warning,#b58a22) 8%,var(--body-bg,#252b33));font-size:11px;line-height:1.45;color:var(--body-text,#e7e9ec)}@media(max-width:700px){.managed-clusters-page{padding:16px 12px}.page-head,.group-row,.assessment-heading{flex-direction:column;align-items:stretch}.group-form,.group-list,.inventory{padding:14px}.assessment-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.assessment-shared-grid{grid-template-columns:1fr}}
</style>

<style scoped>
.resource-comparison{display:grid;gap:3px;padding:6px 0;border-top:1px solid var(--border,#394452)}
.resource-comparison p{margin:2px 0;overflow-wrap:anywhere;font-size:13px}
.resource-comparison p strong{font-size:13px}
.resource-comparison small{overflow-wrap:anywhere}
</style>
